var labels = { planning: "Planning", idle: "No reply", empty: "No pictures", "zero-budget": "Disabled", preparing: "Preparing prompt", rewriting: "Rewriting prompt", rebuilding: "Applying template", "retry-running": "Retry running", "retry-queued": "Retry queued", reused: "Reused", held: "Needs review", failed: "Failed", cancelled: "Cancelled", waiting: "Waiting to generate", generating: "Generating", historical: "Saved", completed: "Ready" };
function pictureStateLabel(state) {
  return state.kind === "cancelled" && state.title === "Picture skipped" ? "Skipped" : labels[state.kind] ?? state.title;
}
function pictureStateSummary(states) {
  if (!states.length)
    return "";
  const counts = new Map;
  for (const state of states) {
    const group = ["completed", "historical", "reused"].includes(state.kind) ? "ready" : state.kind === "preparing" ? "preparing" : pictureStateLabel(state).toLocaleLowerCase();
    counts.set(group, (counts.get(group) ?? 0) + 1);
  }
  const order = ["ready", "needs review", "rewriting prompt", "applying template", "preparing", "waiting to generate", "generating", "retry queued", "retry running", "failed", "cancelled", "skipped"];
  return [`${states.length} picture${states.length === 1 ? "" : "s"}`, ...[...new Set([...order, ...counts.keys()])].filter((key) => counts.has(key)).map((key) => `${counts.get(key)} ${key}`)].join(" · ");
}
function inspectorState(input2) {
  const { asset, requestState } = input2;
  const state = (kind, title, detail, action = null) => ({ kind, title, detail, action });
  if (input2.planning)
    return state("planning", "Planning this reply…", "Picture cues and prompts are not ready yet. You can keep reading.");
  if (!asset) {
    if (!input2.hasTurn)
      return state("idle", "No reply selected", "Open a story reply to inspect its pictures.");
    return input2.zeroBudget ? state("zero-budget", "New pictures are disabled", "The current image budget is zero. This reply has no planned picture requests.") : state("empty", "No pictures planned for this reply", "No new picture requests were planned. You can keep reading.");
  }
  if (input2.operation === "rewrite")
    return state("rewriting", "Rewriting this prompt…", "Using story-reader text tokens. Review the new wording before generating an image.");
  if (input2.operation === "template")
    return state("rebuilding", "Applying this template…", "Preparing new wording and parameters. Your existing picture stays until you approve a replacement.");
  if (input2.preparing)
    return state("preparing", "Preparing a prompt…", "Wait for a new preview. Image generation still needs your approval.");
  if (input2.retryRunning)
    return state("retry-running", "Retry in progress…", "One retry attempt is running. Your existing picture stays while a replacement is prepared and generated.");
  if (input2.retryQueued)
    return state("retry-queued", "Retry queued", "Waiting for current image work or held previews. This retry will use the saved scene and current image settings without review.");
  if (asset.source === "cache")
    return state("reused", "Reused picture", "A saved picture was reused without a new image request.");
  if (requestState === "review")
    return state("held", "Ready for your review", "Review or edit the prompt, then generate this picture. No image request has been sent.", "generate");
  if (asset.status === "failed")
    return state("failed", "Picture failed", "Quick retry starts another image attempt without review. Edit before retry opens a separate preview.", "retry");
  if (asset.status === "cancelled")
    return state("cancelled", requestState === "skipped" ? "Picture skipped" : "Picture cancelled", "Quick retry queues another attempt without review, or edit a preview first.", "retry");
  if (asset.status === "queued" && requestState)
    return state("waiting", "Waiting to generate", "The prompt is prepared and waiting for an image slot. No provider generation is reported yet.");
  if (asset.status === "queued" || asset.status === "generating")
    return requestState ? state("generating", "Generating picture…", "The image request has been approved. You can keep reading.") : state("preparing", "Preparing a prompt…", "Waiting for prompt and reference preparation. Later pictures may depend on an earlier portrait.");
  if (!requestState)
    return state("historical", "Saved picture", "The original request is unavailable for this older picture. You can prepare a new preview.", "prepare");
  return state("completed", "Picture ready", "Regenerate immediately without review, or edit a replacement preview first. Your current picture stays while its replacement runs.", "prepare");
}

