// src/frontend/dom/html.ts
class SafeHtml {
  value;
  constructor(value) {
    this.value = value;
  }
  toString() {
    return this.value;
  }
}
function escapeText(value) {
  return value.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&#39;");
}
