function createMockAudioPlayer(src) {
  const listeners = new Map;
  let currentVolume = 1;
  let isPaused = true;
  return {
    src,
    loop: false,
    currentTime: 0,
    get volume() {
      return currentVolume;
    },
    set volume(val) {
      currentVolume = Math.max(0, Math.min(1, val));
    },
    get paused() {
      return isPaused;
    },
    async play() {
      isPaused = false;
      const playListeners = listeners.get("play");
      playListeners?.forEach((fn) => fn());
    },
    pause() {
      isPaused = true;
      const pauseListeners = listeners.get("pause");
      pauseListeners?.forEach((fn) => fn());
    },
    addEventListener(event, listener) {
      if (!listeners.has(event)) {
        listeners.set(event, new Set);
      }
      listeners.get(event).add(listener);
    },
    removeEventListener(event, listener) {
      listeners.get(event)?.delete(listener);
    }
  };
}
function formatAudioUrl(src) {
  const trimmed = src.trim();
  if (!trimmed)
    return "";
  if (/^[a-zA-Z]:[\\/]/.test(trimmed)) {
    return `file:///${trimmed.replace(/\\/g, "/")}`;
  }
  if (trimmed.startsWith("/") && !trimmed.startsWith("//") && !/^\/(?:api|assets|static|audio|music|sfx|extensions|public|media|files)\//i.test(trimmed)) {
    return `file://${trimmed}`;
  }
  return trimmed;
}
function defaultAudioFactory(src) {
  const formatted = formatAudioUrl(src);
  if (typeof Audio !== "undefined") {
    const audio = new Audio(formatted);
    return audio;
  }
  return createMockAudioPlayer(formatted);
}
