// src/shared/identity.ts
function collapse(value) {
  return value.trim().replace(/\s+/g, " ").replace(/\s*\([^)]*\)\s*/g, " ").replace(/\s+/g, " ").trim();
}
function normalizeCharacterName(value) {
  return typeof value === "string" ? collapse(value) : "";
}
function characterAppearanceKey(name) {
  return normalizeCharacterName(name).toLowerCase();
}
var SPECIES_WORD = "(?:cat|dog|fox|wolf|bunny|rabbit|horse|cow|sheep|goat|deer|mouse|rat|bear|tiger|lion|leopard|panther|dragon|shark|snake|lizard|bird|raven|crow|owl|bat|spider|slime|kitsune|tanuki|neko|inu|usagi|okami|monster|demon|devil|angel|elf|orc|goblin|fairy|beast|animal|anthro|furry)";
var ANATOMY_WORD = "(?:ears?|tails?|paws?|claws?|fangs?|whiskers|fur|scales?|horns?|wings?|fins?|snout|muzzle|teeth|eyes?|hair|markings?|pattern|print|hood|hoodie|mask|plush|plushie|motif|pin|charm|accessory|hairpin|hairclip|ribbon|bow|collar|costume|onesie|pajamas?|slippers?|kigurumi)";
var SPECIES_ANATOMY_COMPOUND = new RegExp(`\\b${SPECIES_WORD}(?:\\s*-?\\s*(?:girl|boy|woman|man|female|male|person|folk|kin))?\\s+${ANATOMY_WORD}\\b`, "gi");

// src/frontend/settings/cast-suggestions.ts
function applyCastSuggestion(draft, source, field, createId, sourceLabel) {
  const setup = structuredClone(draft), notices = [];
  if (field === "appearance") {
    if (source.appearance.trim()) {
      setup.appearance = source.appearance;
      if (sourceLabel?.trim())
        setup.appearanceOrigin = { source: sourceLabel, appearance: source.appearance };
      else if (setup.appearanceOrigin?.appearance !== setup.appearance)
        delete setup.appearanceOrigin;
    } else
      notices.push("This source has no appearance. Existing wording was kept.");
  }
  if (field === "aliases") {
    const seen = new Set(setup.aliases.map(characterAppearanceKey));
    let full = false;
    for (const alias of source.aliases) {
      const key = characterAppearanceKey(alias);
      if (!key || seen.has(key))
        continue;
      if (setup.aliases.length >= 16) {
        full = true;
        continue;
      }
      setup.aliases.push(alias);
      seen.add(key);
    }
    if (full)
      notices.push("The 16-alias limit is reached. Remaining suggestions stay in the source.");
  }
  if (field === "outfits") {
    const key = (name) => name.trim().replace(/\s+/g, " ").toLocaleLowerCase();
    const names = new Map(setup.outfits.map((outfit) => [key(outfit.name), outfit]));
    const ids = new Set(setup.outfits.map((outfit) => outfit.id));
    let full = false;
    for (const outfit of source.outfits) {
      const existing = names.get(key(outfit.name));
      if (existing) {
        if (existing.description !== outfit.description)
          notices.push(`Kept your ${existing.name} outfit; the source has different wording. Review it in Outfits if you want to replace it.`);
        continue;
      }
      if (setup.outfits.length >= 7) {
        full = true;
        continue;
      }
      const id6 = createId();
      if (ids.has(id6)) {
        notices.push(`Could not add ${outfit.name} because its new identifier collided. Try again.`);
        continue;
      }
      const added = { id: id6, name: outfit.name, description: outfit.description };
      setup.outfits.push(added);
      ids.add(id6);
      names.set(key(outfit.name), added);
    }
    if (full)
      notices.push("The seven-outfit limit is reached. Remaining suggestions stay in the source.");
  }
  return { setup, notices, changed: JSON.stringify(setup) !== JSON.stringify(draft) };
}
function appearanceOriginLabel(setup) {
  const origin = setup?.appearanceOrigin;
  if (!origin)
    return "Source not recorded for this appearance.";
  if (origin.appearance !== setup?.appearance)
    return `Appearance edited since selecting ${origin.source}. Saving will clear that previous source note.`;
  return `Selected source: ${origin.source}. This records the saved wording’s source; it does not verify the current story state.`;
}

// src/frontend/settings/cast-art.ts
