    this.el("[data-art-reset]").textContent = "Reset place library";
    const menu = document.createElement("details");
    menu.innerHTML = "<summary>More place actions</summary>";
    menu.append(this.el("[data-art-forget-place]"));
    this.el("[data-art-catalog]").append(menu);
    const listMenu = document.createElement("details");
    listMenu.innerHTML = "<summary>More list actions</summary>";
    this.host.insertBefore(listMenu, list);
    listMenu.append(this.el("[data-art-refresh]"), this.el("[data-art-reset]"));
    const confirm = document.createElement("div");
