        action: template.subjectMode === "none" ? template.category === "detail" ? "An old brass key on a wooden table." : "" : brief?.action ?? "Looking toward a rain-streaked window.",
        composition: `${template.framing}, ${template.subjectMode === "none" ? "without people" : template.subjectMode === "ensemble" ? "all listed scene characters, including persona" : "one visible character"}`,
