      systemOneApiUrl: this.control("systemOneApiUrl").value.trim() || DEFAULT_CONFIG.systemOneApiUrl,
      systemOneModel: this.control("systemOneModel").value.trim() || DEFAULT_CONFIG.systemOneModel,
      imageParameters: keys.includes("imageParameters") ? jsonObject(this.control("imageParameters").value, "Image parameters") : this.config.imageParameters,
      audioDirectory: this.control("audioDirectory").value.trim(),
      includeRecentMessages: clamp(Math.round(Number(this.control("includeRecentMessages").value)), 0, 30, DEFAULT_CONFIG.includeRecentMessages),
