function comparisonVersions(value) {
  if (!Array.isArray(value))
    return [];
  const result = [];
  const seen = new Set;
  for (const entry of value.slice(-1000)) {
    const parsed = ImageVersionSchema.safeParse(entry);
    if (parsed.success && !seen.has(parsed.data.versionId)) {
      seen.add(parsed.data.versionId);
      result.push(parsed.data);
    }
  }
  return result.slice(-50);
}

