// src/shared/image-model-output.ts
var KLEIN_OUTPUT_SIZES = ["768x768", "1024x1024", "1536x1536", "2048x2048", "4096x4096"];
var ANIMA_MODELS = new Set(["anima", "anima/text-to-image", "anima/text-to-image-lora", "wavespeed-ai/anima/text-to-image", "wavespeed-ai/anima/text-to-image-lora"]);
function imageOutputRule(provider, model) {
  if (provider?.trim().toLowerCase() !== "nanogpt")
    return null;
  const id8 = model?.trim().toLowerCase() ?? "";
  if (ANIMA_MODELS.has(id8))
    return "anima";
  if (id8 === "qwen-image-2.1-turbo")
    return "qwen-turbo";
  return ["blackforestlabs/flux-3/klein/base/text-to-image", "blackforestlabs/flux-3/klein/text-to-image"].includes(id8) ? "klein-square" : null;
}
function modelOutputHelp(provider, model, parameters) {
  const rule = imageOutputRule(provider, model);
  if (rule === "qwen-turbo")
    return `Qwen Image 2.1 Turbo uses size "1k" or "2k" and separate framing (${String(parameters.aspectRatio ?? "1:1")}). 9:16 is supported. Other requested shapes use the closest supported ratio before review. The prepared resolution is ${String(parameters.size ?? "1k")}. Custom connection raw overrides take priority; prepare a new preview after changing connection settings.`;
  if (rule === "klein-square")
    return `FLUX.3 Klein supports square images only; 9:16 is unavailable with this model. Visible size field: ${String(parameters.size ?? "1024x1024")}. Supported sizes: ${KLEIN_OUTPUT_SIZES.join(", ")}. A connection's custom raw override takes priority and may change these fields.`;
  if (rule === "anima")
    return `Anima uses size "1k" or "1.5k" with a separate aspectRatio (9:16 is supported for text-to-image). Visible size field: ${String(parameters.size ?? "1k")}; framing: ${String(parameters.aspectRatio ?? "connection default")}. With an image reference, Anima keeps the reference's aspect ratio. A connection's custom raw override takes priority and may change these fields.`;
  return "";
}

// src/shared/build-info.ts
var LUMIGLYPHICS_VERSION = "0.2.0-beta.131";

// src/shared/prompt-length.ts
var IMAGE_PROMPT_MAX_CHARS = 3000;
function compactPromptText(text, force = false) {
  if (!force && text.length <= IMAGE_PROMPT_MAX_CHARS)
    return text;
  const seen = new Set;
  return text.split(/\r?\n/).map((line) => line.trim()).filter((line) => {
    if (!line || seen.has(line))
      return false;
    seen.add(line);
    return true;
  }).join(`
`);
}
function compactNegativePrompt(text) {
  const seen = new Set;
  return compactPromptText(text, true).split(",").map((part) => part.trim()).filter((part) => {
    const key = part.toLocaleLowerCase();
    if (!key || seen.has(key))
      return false;
    seen.add(key);
    return true;
  }).join(", ");
}
function assertPromptLengths(prompt2, negative = "", profile) {
  const total = prompt2.length + negative.length;
  const maximum = profile?.maxCharacters ?? IMAGE_PROMPT_MAX_CHARS;
  if (total > maximum)
    throw new Error(`Combined positive and negative prompts are ${total.toLocaleString()} characters (${prompt2.length.toLocaleString()} positive + ${negative.length.toLocaleString()} negative). Shorten them to ${maximum.toLocaleString()} characters total or fewer; unique details were not silently removed.`);
  if (profile?.negativeMode === "positive-only" && negative.trim())
    throw new Error("This endpoint requires positive-only wording. Regenerate the prompt to incorporate essential constraints into the positive description, or clear the negative field after reviewing it.");
}
function fitPromptToBudget(prompt2, negative = "", maxCharacters = IMAGE_PROMPT_MAX_CHARS, negativeMode) {
  let effectiveNegative = negativeMode === "positive-only" ? "" : compactNegativePrompt(negative);
  let effectivePrompt = compactPromptText(prompt2, true);
  if (effectivePrompt.length + effectiveNegative.length <= maxCharacters) {
    return { prompt: effectivePrompt, negativePrompt: effectiveNegative, fitted: false };
  }
  const deduplicateTags = (text) => {
    const seen = new Set;
    const tags = text.split(/,\s*|\r?\n/).map((t) => t.trim()).filter(Boolean);
    const result = [];
    for (const tag of tags) {
      const lower = tag.toLowerCase();
      const isAnchorOrWeight = tag.startsWith("(") || tag.includes(":") || tag.startsWith("[") || tag.includes("anchor");
      if (isAnchorOrWeight || !seen.has(lower)) {
        if (!isAnchorOrWeight)
          seen.add(lower);
        result.push(tag);
      }
    }
    return result.join(", ");
  };
  effectivePrompt = deduplicateTags(effectivePrompt);
  if (effectiveNegative) {
    effectiveNegative = deduplicateTags(effectiveNegative);
  }
  if (effectivePrompt.length + effectiveNegative.length <= maxCharacters) {
    return { prompt: effectivePrompt, negativePrompt: effectiveNegative, fitted: true };
  }
  const maxNegative = negativeMode === "positive-only" ? 0 : Math.min(effectiveNegative.length, Math.floor(maxCharacters * 0.15));
  if (effectiveNegative.length > maxNegative) {
    const negTags = effectiveNegative.split(/,\s*/);
    let curNeg = "";
    for (const tag of negTags) {
      const candidate = curNeg ? `${curNeg}, ${tag}` : tag;
      if (candidate.length <= maxNegative) {
        curNeg = candidate;
      } else {
        break;
      }
    }
    effectiveNegative = curNeg;
  }
  const allowedPositive = Math.max(100, maxCharacters - effectiveNegative.length);
  if (effectivePrompt.length > allowedPositive) {
    const tags = effectivePrompt.split(/,\s*|\r?\n/).map((t) => t.trim()).filter(Boolean);
    let curPrompt = "";
    for (const tag of tags) {
      const candidate = curPrompt ? `${curPrompt}, ${tag}` : tag;
      if (candidate.length <= allowedPositive) {
        curPrompt = candidate;
      } else {
        break;
      }
    }
    effectivePrompt = curPrompt || effectivePrompt.slice(0, allowedPositive).replace(/\s+\S*$/, "");
  }
  return {
    prompt: effectivePrompt.trim(),
    negativePrompt: effectiveNegative.trim(),
    fitted: true
  };
}

// src/frontend/image-review/focus-trap.ts
var MOBILE_CONTAINER_MAX_WIDTH_PX = 600;
function isMobileWidth(host) {
  const width = host.getBoundingClientRect().width;
  return width > 0 && width <= MOBILE_CONTAINER_MAX_WIDTH_PX;
}
var FOCUSABLE_SELECTOR = [
  "button:not(:disabled)",
  "select:not(:disabled)",
  "input:not(:disabled)",
  "textarea:not(:disabled)",
  "summary",
  "a[href]",
  '[tabindex]:not([tabindex="-1"])'
].join(",");
function trapFocusWithin(container, event, active) {
  const focusable = [...container.querySelectorAll(FOCUSABLE_SELECTOR)].filter((el) => !el.hidden && !el.closest("[hidden]") && (typeof el.getClientRects !== "function" || el.getClientRects().length > 0));
  const first = focusable[0];
  const last = focusable.at(-1);
  if (!first || !last)
    return;
  if (event.shiftKey && active === first) {
    event.preventDefault();
    last.focus({ preventScroll: true });
  } else if (!event.shiftKey && active === last) {
    event.preventDefault();
    first.focus({ preventScroll: true });
  }
}

