// src/frontend/host/panel-capture.ts
function captureSimTrackerCards(message, document2) {
  const sources = [...message?.querySelectorAll(".sst-message-tracker-host") ?? [], ...document2.querySelectorAll(".sst-side-tracker-root")];
  const results = [];
  for (const source of sources.slice(0, MAX_PANELS)) {
    const clone2 = source.cloneNode(true);
    const originalInputs = source.querySelectorAll("input");
    clone2.querySelectorAll("input").forEach((input2, index) => {
      input2.toggleAttribute("checked", originalInputs[index]?.checked ?? false);
    });
    const html2 = clone2.innerHTML;
    if (html2.length > MAX_PANEL_HTML)
      continue;
    results.push({ title: source.classList.contains("sst-side-tracker-root") ? "SimTracker sidebar" : "SimTracker", html: html2 });
  }
  return results;
}

