function describeStatus(status) {
  switch (status.kind) {
    case "off":
      return "";
    case "idle":
      return status.speaker ? `Speech ready — ${status.speaker}` : "Speech ready";
    case "loading":
      return "Fetching audio…";
    case "playing":
      return status.speaker ? `Speaking — ${status.speaker}` : "Speaking";
    case "paused":
      return "Paused";
    case "blocked":
      return status.message;
    case "unconfigured":
      return status.message;
    case "error":
      return status.message;
  }
}

