    if (!this.settings.characters[key])
      this.pendingOverrideNames.add(key);
    this.draftAddName = "";
    this.render();
    const suffix = key.slice(`chat::${chatId}::`.length);
    const row = [...this.shadow.querySelectorAll("[data-speech-override-row],[data-speech-draft-row]")].find((el) => (el.getAttribute("data-speech-override-row") ?? el.getAttribute("data-speech-draft-row")) === suffix);
